import org.jsoup.nodes.Document;
import org.jsoup.nodes.TextNode;

public class TextNode {
    private String nodeName;
    private String text;

    public TextNode(StringnodeName, String text) {
        this.nodeName = nodeName;
        this.text = text;
    }

    public String getWholeText() {
        return text;
    }

    public boolean isBlank() {
        return text.isEmpty();
    }

    public void setNodeName(String nodeName) {
        this.nodeName = nodeName;
    }

    @Override
    public String toString() {
        return "TextNode{" +
                "nodeName='" + nodeName + '\'' +
                ", text='" + text + '\'' +
                '}';
    }
}

public class TestRunner {
    public static void main(String[] args) {
        Document document = new Document();
        document.write("<p>Hello, World!</p>");
        document.write("</p>");

        TextNode root = new TextNode("root", document.body().text());
        document.write(root.toString());

        String text = "Hello, World!";
        System.out.println(new TestRunner().runTest("root", text));
    }

    public static String runTest(TextNode node, String text) {
        if (node.nodeName.equals("p")) {
            return new TestRunner().trimText(node.getWholeText());
        } else {
            return new TestRunner().trimText(text);
        }
    }

    private static String trimText(String text) {
        StringBuilder result = new StringBuilder();
        for (char c : text.toCharArray()) {
            if (!Character.isWhitespace(c)) {
                result.append(c);
            }
        }
        return result.toString();
    }
}
