import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;

public class TextNode {
    private String nodeName;
    private int textLength;

    public TextNode(String nodeName, int textLength) {
        this.nodeName = nodeName;
        this.textLength = textLength;
    }

    public String getNodeName() {
        return nodeName;
    }

    public void setNodeName(String nodeName) {
        this.nodeName = nodeName;
    }

    @Override
    public String toString() {
        return "TextNode{" +
                "nodeName='" + nodeName + '\'' +
                ", text=" + textLength +
                '}';
    }
}

public class TestRunner {
    public static void main(String[] args) {
        Document document = new Document();
        document.write("<p>Hello, World!</p>");
        document.write("</p>");

        TextNode root = new TextNode("root", 0);
        document.getElementById(root.getNodeName()).setText(root.getWholeText());
        document.getElementById("root").style.textDecoration = "underline";

        String text = "Hello, World!";
        System.out.println(new TestRunner().runTest(text));
    }

    public static String runTest(String text) {
        if (text.length() == 0) {
            return "";
        }
        String trimmedText = new TestRunner().trimText(text);
        TextNode node = new TextNode(trimmedText, 1);
        return node.getWholeText();
    }

    private static String trimText(String text) {
        int start = 0;
        while (start < text.length() && Character.isWhitespace(text.charAt(start))) {
            start++;
        }
        int end = text.length() - 1;
        while (end >= 0 && Character.isWhitespace(text.charAt(end))) {
            end--;
        }
        return text.substring(start, end + 1);
    }
}
